  --color-border-error: #dc2626;
  --color-text: #111827;
  --color-text-muted: #6b7280;
  --color-label: #374151;
  --color-required: #dc2626;
  --color-help: #6b7280;
  --color-error: #dc2626;
  --color-btn-bg: #4f46e5;
  --color-btn-bg-hover: #4338ca;
  --color-btn-text: #ffffff;
  --color-btn-reset-bg: transparent;
  --color-btn-reset-border: #4f46e5;
  --color-btn-reset-text: #4f46e5;
  --color-success-icon: #16a34a;
  --color-header-bg: #ffffff;
  --color-header-border: #e5e7eb;

  --radius-input: 8px;
  --radius-card: 16px;
  --radius-btn: 8px;

  --shadow-card: 0 4px 24px rgba(0, 0, 0, 0.08);
  --shadow-focus: 0 0 0 3px rgba(79, 70, 229, 0.35);
  --shadow-focus-error: 0 0 0 3px rgba(220, 38, 38, 0.3);

  --transition: 0.15s ease;
}

/* ============================================================
   Reset / base
   ============================================================ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 100%;
  -webkit-text-size-adjust: 100%;
}

body {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100dvh;
}

/* ============================================================
   Skip link
   ============================================================ */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 100;
  padding: 0.5rem 1rem;
  background: var(--color-btn-bg);
  color: var(--color-btn-text);
  border-radius: var(--radius-btn);
  font-weight: 600;
  text-decoration: none;
}

.skip-link:focus {
  top: 1rem;
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* ============================================================
   Header
   ============================================================ */
.site-header {
  background: var(--color-header-bg);
  border-bottom: 1px solid var(--color-header-border);
  padding: 0 1.5rem;
  height: 56px;
  display: flex;
  align-items: center;
}

.site-header__inner {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  max-width: 72rem;
  width: 100%;
  margin: 0 auto;
}

.site-header__logo {
  font-size: 1.4rem;
  color: var(--color-btn-bg);
}

.site-header__brand {
  font-weight: 700;
  font-size: 1.0625rem;
  letter-spacing: -0.01em;
  color: var(--color-text);
}

/* ============================================================
   Page layout
   ============================================================ */
.page-layout {
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 3rem 1rem 4rem;
  min-height: calc(100dvh - 56px);
}

/* ============================================================
   Form card
   ============================================================ */
.form-card {
  background: var(--color-surface);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  padding: 2.5rem 2rem;
  width: 100%;
  max-width: 480px;
}

.form-card__heading {
  margin-bottom: 1.75rem;
}

.form-card__heading h1 {
  font-size: 1.625rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
  line-height: 1.25;
}

.form-card__subtitle {
  margin-top: 0.375rem;
  font-size: 0.9375rem;
  color: var(--color-text-muted);
}

/* Required-fields note */
.required-note {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  margin-bottom: 1.5rem;
}

/* ============================================================
   Form fields
   ============================================================ */
#contact-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.form-field__label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-label);
  display: flex;
  align-items: center;
  gap: 0.2rem;
}

.required-marker {
  color: var(--color-required);
  font-size: 1rem;
  line-height: 1;
}

.form-field__optional {
  font-weight: 400;
  font-size: 0.875rem;
  color: var(--color-text-muted);
  margin-left: 0.25rem;
}

.form-field__input {
  display: block;
  width: 100%;
  padding: 0.625rem 0.875rem;
  font-size: 1rem;
  font-family: inherit;
  color: var(--color-text);
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-input);
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
  -webkit-appearance: none;
  appearance: none;
}

.form-field__input:hover {
  border-color: #9ca3af;
}

.form-field__input:focus {
  border-color: var(--color-border-focus);
  box-shadow: var(--shadow-focus);
}

.form-field__input[aria-invalid="true"] {
  border-color: var(--color-border-error);
}

.form-field__input[aria-invalid="true"]:focus {
  box-shadow: var(--shadow-focus-error);
}

.form-field__help {
  font-size: 0.8125rem;
  color: var(--color-help);
  margin-top: 0.125rem;
}

.form-field__error {
  font-size: 0.875rem;
  color: var(--color-error);
  font-weight: 500;
  margin-top: 0.125rem;
}

/* ============================================================
   Submit button
   ============================================================ */
.form-actions {
  margin-top: 0.5rem;
}

.btn-submit {
  display: block;
  width: 100%;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  color: var(--color-btn-text);
  background: var(--color-btn-bg);
  border: none;
  border-radius: var(--radius-btn);
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition);
  outline: none;
}

.btn-submit:hover {
  background: var(--color-btn-bg-hover);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

.btn-submit:active {
  transform: translateY(1px);
}

/* ============================================================
   Success panel
   ============================================================ */
.success-panel {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 1rem 0;
  gap: 0.75rem;
}

.success-panel__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 3rem;
  height: 3rem;
  border-radius: 50%;
  background: #dcfce7;
  color: var(--color-success-icon);
  font-size: 1.5rem;
  font-weight: 700;
}

.success-panel__heading {
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--color-text);
}

.success-panel__body {
  font-size: 0.9375rem;
  color: var(--color-text-muted);
  max-width: 340px;
}

.btn-reset {
  margin-top: 0.5rem;
  padding: 0.625rem 1.25rem;
  font-size: 0.9375rem;
  font-weight: 600;
  font-family: inherit;
  color: var(--color-btn-reset-text);
  background: var(--color-btn-reset-bg);
  border: 1.5px solid var(--color-btn-reset-border);
  border-radius: var(--radius-btn);
  cursor: pointer;
  transition: background var(--transition);
  outline: none;
}

.btn-reset:hover {
  background: #ede9fe;
}

.btn-reset:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* ============================================================
   Visually hidden (for live regions & SR-only text)
   ============================================================ */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* ============================================================
   Reduced motion
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ============================================================
   Forced colors (Windows high-contrast)
   ============================================================ */
@media (forced-colors: active) {
  .form-field__input {
    border: 2px solid ButtonText;
  }
  .btn-submit,
  .btn-reset {
    forced-color-adjust: none;
  }
}

/* ============================================================
   Reflow — narrow viewports (320 px)
   ============================================================ */
@media (max-width: 480px) {
  .form-card {
    padding: 1.75rem 1.25rem;
    border-radius: 12px;
  }

  .form-card__heading h1 {
    font-size: 1.375rem;
  }

  .page-layout {
    padding: 1.5rem 0.75rem 3rem;
  }
}
