  'use strict';

  // Phone: allow common formats — digits, spaces, dashes, dots, parens, leading +
  const PHONE_PATTERN = /^[+]?[\d\s\-().]{7,20}$/;

  const form         = document.getElementById('contact-form');
  const successPanel = document.getElementById('success-panel');
  const resetBtn     = document.getElementById('reset-btn');
  const statusRegion = document.getElementById('form-success');

  // Field descriptors — keeps validation logic data-driven
  const fields = [
    {
      id:        'full-name',
      errorId:   'full-name-error',
      required:  true,
      validate(value) {
        if (!value.trim()) return 'Error: Full name is required.';
        return null;
      },
    },
    {
      id:       'email',
      errorId:  'email-error',
      required: true,
      validate(value) {
        if (!value.trim()) return 'Error: Email address is required.';
        // Basic RFC-friendly check; the browser type="email" handles more
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
          return 'Error: Enter a valid email address, e.g. name@example.com.';
        }
        return null;
      },
    },
    {
      id:       'phone',
      errorId:  'phone-error',
      required: false,
      validate(value) {
        if (!value.trim()) return null; // optional
        if (!PHONE_PATTERN.test(value.trim())) {
          return 'Error: Enter a valid phone number, e.g. +1 (555) 000-0000.';
        }
        return null;
      },
    },
  ];

  /* ------------------------------------------------------------------ */
  /* Helpers                                                              */
  /* ------------------------------------------------------------------ */

  function getInput(fieldDef) {
    return document.getElementById(fieldDef.id);
  }

  function getErrorEl(fieldDef) {
    return document.getElementById(fieldDef.errorId);
  }

  function showError(fieldDef, message) {
    const input   = getInput(fieldDef);
    const errorEl = getErrorEl(fieldDef);
    errorEl.textContent = message;
    errorEl.hidden = false;
    input.setAttribute('aria-invalid', 'true');
  }

  function clearError(fieldDef) {
    const input   = getInput(fieldDef);
    const errorEl = getErrorEl(fieldDef);
    errorEl.hidden = true;
    errorEl.textContent = '';
    input.removeAttribute('aria-invalid');
  }

  /* ------------------------------------------------------------------ */
  /* Inline (blur-time) validation                                        */
  /* ------------------------------------------------------------------ */

  fields.forEach((fieldDef) => {
    const input = getInput(fieldDef);

    input.addEventListener('blur', () => {
      const error = fieldDef.validate(input.value);
      if (error) {
        showError(fieldDef, error);
      } else {
        clearError(fieldDef);
      }
    });

    // Clear error as soon as the field becomes valid while typing
    input.addEventListener('input', () => {
      if (input.getAttribute('aria-invalid') === 'true') {
        const error = fieldDef.validate(input.value);
        if (!error) clearError(fieldDef);
      }
    });
  });

  /* ------------------------------------------------------------------ */
  /* Submit handler                                                       */
  /* ------------------------------------------------------------------ */

  form.addEventListener('submit', (event) => {
    event.preventDefault();

    // Validate all fields and collect errors
    const errors = [];
    fields.forEach((fieldDef) => {
      const input = getInput(fieldDef);
      const error = fieldDef.validate(input.value);
      if (error) {
        showError(fieldDef, error);
        errors.push({ fieldDef, input });
      } else {
        clearError(fieldDef);
      }
    });

    if (errors.length > 0) {
      // Move focus to the first invalid field
      errors[0].input.focus();
      return;
    }

    // Success — hide form, show success panel, announce via live region
    form.hidden = true;
    successPanel.hidden = false;
    statusRegion.textContent = 'Your message has been sent successfully.';
    resetBtn.focus();
  });

  /* ------------------------------------------------------------------ */
  /* Reset — let user send another message                               */
  /* ------------------------------------------------------------------ */

  resetBtn.addEventListener('click', () => {
    // Clear all errors and reset field values
    fields.forEach((fieldDef) => {
      clearError(fieldDef);
      getInput(fieldDef).value = '';
    });

    statusRegion.textContent = '';
    successPanel.hidden = true;
    form.hidden = false;

    // Return focus to the first field
    getInput(fields[0]).focus();
  });
})();
