      id:       'phone',
      errorId:  'phone-error',
      required: false,
      validate(value) {
        if (!value.trim()) return null; // optional
        if (!PHONE_PATTERN.test(value.trim())) {
          return 'Error: Enter a valid phone number, e.g. +1 (555) 000-0000.';
        }
        return null;
      },
    },
  ];

