    fields.forEach((fieldDef) => {
      const input = getInput(fieldDef);
      const error = fieldDef.validate(input.value);
      if (error) {
        showError(fieldDef, error);
        errors.push({ fieldDef, input });
      } else {
        clearError(fieldDef);
      }
    });

    if (errors.length > 0) {
      // Move focus to the first invalid field
      errors[0].input.focus();
      return;
    }

    // Success — hide form, show success panel, announce via live region
    form.hidden = true;
    successPanel.hidden = false;
    statusRegion.textContent = 'Your message has been sent successfully.';
    resetBtn.focus();
  });

  /* ------------------------------------------------------------------ */
  /* Reset — let user send another message                               */
  /* ------------------------------------------------------------------ */

  resetBtn.addEventListener('click', () => {
    // Clear all errors and reset field values
    fields.forEach((fieldDef) => {
      clearError(fieldDef);
      getInput(fieldDef).value = '';
    });

    statusRegion.textContent = '';
    successPanel.hidden = true;
    form.hidden = false;

    // Return focus to the first field
    getInput(fields[0]).focus();
  });
})();
